arguments.old:
difference() {
    union() {
        gear_solid(z1);
        // detent plate on the gear, dipping 0.7 below the gear top so
        // its underside bridges only 0.6 above the gear top face
        translate([0, 0, gear_h - 0.7]) cylinder(r = 12, h = 3.2, $fn = 72);
        // crank peg, standing up at radius 7.5 (clear of the notches)
        translate([0, 7.5, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
    }
    translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
    // four deep V notches: the base bump clicks in every quarter turn
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a]) translate([0, -10.6, gear_h - 1.5])
            cylinder(r1 = 2.6, r2 = 1.2, h = 4.2, $fn = 32);
}

arguments.new:
difference() {
    union() {
        gear_solid(z1);
        // detent plate on the gear, underside flush with the gear top,
        // with a 45 deg conical lead-in from the gear OD
        translate([0, 0, gear_h]) cylinder(r = 12, h = 2.5, $fn = 72);
        translate([0, 0, gear_h - 1]) cylinder(r1 = 15.2, r2 = 12, h = 1, $fn = 72);
        // crank peg, standing up at radius 7.5 (clear of the notches)
        translate([0, 7.5, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
    }
    translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
    // four deep V notches (blind: 1.5 mm of roof above the cavity):
    // the base bump clicks in every quarter turn
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a]) translate([0, -10.6, gear_h - 2])
            cylinder(r1 = 2.6, r2 = 1.2, h = 3, $fn = 32);
}
